-- Postgres foundation. Review migration on staging before applying. Not used by the demo routes.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),locale text NOT NULL DEFAULT 'fa',status text NOT NULL DEFAULT 'pending');
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),project_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES sessions(id),role text NOT NULL CHECK(role IN ('user','assistant','system')),content jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_skus(id text PRIMARY KEY,provider text NOT NULL DEFAULT 'higgsfield',display_name text NOT NULL,kind text NOT NULL CHECK(kind IN ('image','video')),configuration jsonb NOT NULL,neuron_price integer NOT NULL CHECK(neuron_price>0),version integer NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT false,verified_provider_path text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fx_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),usd_sell_toman bigint NOT NULL CHECK(usd_sell_toman>0),source text NOT NULL,observed_at timestamptz NOT NULL,valid_until timestamptz NOT NULL,raw_evidence jsonb NOT NULL DEFAULT '{}'::jsonb,approved boolean NOT NULL DEFAULT false);
CREATE TABLE package_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid REFERENCES accounts(id),fx_quote_id uuid REFERENCES fx_quotes(id),price_toman bigint NOT NULL CHECK(price_toman>0),base_neurons bigint NOT NULL CHECK(base_neurons>=0),gift_neurons bigint NOT NULL CHECK(gift_neurons>=0),bonus_percent integer NOT NULL CHECK(bonus_percent BETWEEN 0 AND 100),quoted_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,consumed_at timestamptz,CHECK(expires_at>quoted_at));
CREATE TABLE wallets(account_id uuid PRIMARY KEY REFERENCES accounts(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES wallets(account_id),transaction_id text NOT NULL,kind text NOT NULL CHECK(kind IN ('purchase','reserve','settle','release','refund')),neurons bigint NOT NULL CHECK(neurons>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,transaction_id,kind));
CREATE TABLE payment_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),package_quote_id uuid NOT NULL REFERENCES package_quotes(id),provider_ref text UNIQUE,status text NOT NULL CHECK(status IN ('pending','verified','rejected','refunded')),verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE generation_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),session_id uuid NOT NULL REFERENCES sessions(id),sku_id text NOT NULL REFERENCES media_skus(id),sku_version integer NOT NULL,neuron_price bigint NOT NULL CHECK(neuron_price>0),parameters jsonb NOT NULL,reference_ids uuid[] NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE generation_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),generation_quote_id uuid NOT NULL UNIQUE REFERENCES generation_quotes(id),account_id uuid NOT NULL REFERENCES accounts(id),idempotency_key text NOT NULL UNIQUE,state text NOT NULL CHECK(state IN ('quoted','awaiting_approval','queued','running','completed','failed','canceled')),provider_request_id text UNIQUE,provider_actual_usd_micros bigint,started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),generation_job_id uuid REFERENCES generation_jobs(id),storage_key text NOT NULL UNIQUE,media_kind text NOT NULL CHECK(media_kind IN ('image','video')),metadata jsonb NOT NULL DEFAULT '{}'::jsonb,parent_asset_id uuid REFERENCES media_assets(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ON generation_jobs(account_id,created_at DESC);
CREATE INDEX ON media_assets(account_id,created_at DESC);
CREATE INDEX ON wallet_events(account_id,created_at DESC);
-- Important: applying these tables does NOT implement atomic holds/settlements.
-- Implement transactional wallet operations with row locks and verified payment webhooks.
